	var text string
	switch u.Status {
	case gitcli.RefCreated:
		text = plural(u.Commits, "commit", "commits")
	case gitcli.RefUpdated:
		text = "+" + plural(u.Commits, "commit", "commits")
	case gitcli.RefDiverged:
